// Version A: shared singleton
const store: Record<string, any> = {}
export function setValue(key: string, v: any) { store[key] = v }
export function getValue(key: string) { return store[key] }

// Version B: passed in store
export function setValueV2(storeParam: Record<string, any>, key: string, v: any) { storeParam[key] = v }
export function getValueV2(storeParam: Record<string, any>, key: string) { return storeParam[key] }
